@pytest.mark.req("R6") @pytest.mark.parametrize("commits_before_cut", [0, 1, 2]) @pytest.mark.parametrize("op", ["relay on", "relay off"]) def test_DI04_power_cut_between_flash_writes(dut, op, commits_before_cut, record_property): """TC-DI-04: supply cut after K flash (NVS) entry writes of a state update -> after power-on the state is exactly the old one or exactly the new one (counter and relay must belong to the same version).""" pre = "relay off" if op == "relay on" else "relay on" # learn what one state update looks like (counter delta) on this build dut.cmd(pre); dut.wait(200) c0 = dut.status()["counter"] dut.cmd(op); dut.wait(200) delta = dut.status()["counter"] - c0 dut.cmd(pre); dut.wait(300) old = dut.status() old_v = (old["counter"], bool(old["relay"])) new_v = (old["counter"] + delta, op == "relay on") n = dut.boot_count dut.hw(f"NVSCUT {commits_before_cut} POWERON") dut.send(op) try: dut.wait_boot(n, timeout=1500) cut = True except AssertionError: cut = False # update needed fewer flash writes than K: nothing was interrupted dut.hw("NVSCUT -1 POWERON") dut.power_cycle(off_ms=500) after = dut.wait_ready(READY_MS) got = (after["counter"], bool(after["relay"])) record_property("cut_happened", cut) record_property("old", old_v) record_property("new", new_v) record_property("after_power_on", got) > assert got in (old_v, new_v), f"mixed state after power cut: got {got}, allowed old {old_v} or new {new_v}" E AssertionError: mixed state after power cut: got (4, False), allowed old (3, False) or new (4, True) E assert (4, False) in ((3, False), (4, True))
